create extension if not exists "uuid-ossp";
create type public.app_role as enum ('ADMIN','MANAGER','MEMBER');
create type public.transaction_kind as enum ('INCOME','EXPENSE');
create table public.companies (id uuid primary key default uuid_generate_v4(), name text not null, niche text, plan text not null default 'BASIC', created_at timestamptz default now());
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, company_id uuid references public.companies(id) on delete cascade, full_name text not null, role public.app_role default 'MEMBER', created_at timestamptz default now());
create table public.transactions (id uuid primary key default uuid_generate_v4(), company_id uuid references public.companies(id) on delete cascade not null, kind public.transaction_kind not null, date date default current_date, description text not null, category text default 'Outros', amount numeric(14,2) check(amount > 0) not null, source text, status text default 'PENDING', created_by uuid references auth.users(id), created_at timestamptz default now());
create table public.team_members (id uuid primary key default uuid_generate_v4(), company_id uuid references public.companies(id) on delete cascade not null, name text not null, type text check(type in ('HUMAN','AI')) not null, role text not null, performance numeric default 0, target numeric default 0, monthly_cost numeric default 0, roi numeric default 0, status text default 'ACTIVE');
create table public.meetings (id uuid primary key default uuid_generate_v4(), company_id uuid references public.companies(id) on delete cascade not null, title text not null, date timestamptz not null, participants jsonb default '[]', notes text default '', transcript text default '');
create table public.action_items (id uuid primary key default uuid_generate_v4(), meeting_id uuid references public.meetings(id) on delete cascade not null, title text not null, owner_id uuid references public.team_members(id), due date, done boolean default false);
create table public.audit_log (id uuid primary key default uuid_generate_v4(), company_id uuid references public.companies(id) on delete cascade, actor_id uuid references auth.users(id), action text not null, entity text not null, entity_id text, metadata jsonb default '{}', created_at timestamptz default now());
alter table public.companies enable row level security; alter table public.profiles enable row level security; alter table public.transactions enable row level security; alter table public.team_members enable row level security; alter table public.meetings enable row level security; alter table public.action_items enable row level security; alter table public.audit_log enable row level security;
create or replace function public.my_company_id() returns uuid language sql stable security definer set search_path=public as $$ select company_id from public.profiles where id=auth.uid() $$;
create policy company_transactions on public.transactions for all using(company_id=public.my_company_id()) with check(company_id=public.my_company_id());
create policy company_team on public.team_members for all using(company_id=public.my_company_id()) with check(company_id=public.my_company_id());
create policy company_meetings on public.meetings for all using(company_id=public.my_company_id()) with check(company_id=public.my_company_id());
